"""Revalidate phase1 after origin bookkeeping/closure separation; no phase2 resume."""
import importlib.util,json,pathlib,sys
sys.dont_write_bytecode=True
P=pathlib.Path(__file__).resolve().parent
s=importlib.util.spec_from_file_location('repair_fixed',P/'repair_contract.py');rc=importlib.util.module_from_spec(s);s.loader.exec_module(rc)
def read(n):return json.loads((P/(n+'.json')).read_text(encoding='utf-8-sig'))
def write(n,x):(P/(n+'.json')).write_text(json.dumps(x,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
tests=rc.six_state_tests();assert len(tests)==6 and all(t['PASS'] for t in tests) and len({t['ACTUAL_STATUS'] for t in tests})==6
unknown={k:'NOT_ESTABLISHED' for k in rc.FIELDS};created={k:'YES' for k in rc.FIELDS[:4]};created.update(ARTIFACT_EXISTS='YES',ARTIFACT_AUTHENTICATED='NOT_ESTABLISHED',ARTIFACT_ADMITTED='NOT_ESTABLISHED');all_yes={k:'YES' for k in rc.FIELDS}
controls=[dict(control='Unknown facts never imply normative/runtime/underspec/contradiction',passed=rc.classify(unknown,{}) is None),dict(control='Creation/hash alone never authenticate or close',passed=rc.classify(created,dict(created_by_c5r=True,hash_present=True)) is None and not rc.closure_eligible(created,dict(created_by_c5r=True,hash_present=True))),dict(control='Self-asserted authentication lacks independent proof',passed=rc.classify({**created,'ARTIFACT_AUTHENTICATED':'YES'},dict(origin='PRE_EXISTING')) is None),dict(control='Independent admission proof still required',passed=not rc.closure_eligible(all_yes,dict(independent_authentication_proved=True))),dict(control='Bookkeeping origin is NOT additional closure predicate',passed=rc.closure_eligible(all_yes,dict(independent_authentication_proved=True,independent_admission_proved=True))),dict(control='Positive frozen contradiction blocks closure despite claimed positive flags',passed=not rc.closure_eligible(all_yes,dict(independent_authentication_proved=True,independent_admission_proved=True,frozen_authority_contradiction_proved=True)))]
assert all(c['passed'] for c in controls)
write('repair-six-state-tests',dict(REPAIR_TESTS_REQUIRED=6,REPAIR_TESTS_PASSING=6,REPAIR_TESTS_FAILING=0,tests=tests,additional_controls=controls,all_cases_synthetic=True,actual_artifacts_created=0,actual_blocker_closures=0,no_witness_execution=True,validation_revision=2))
write('phase1-correction',dict(reason='Removed extra origin-label bookkeeping requirement from closure_eligible; §16 closure depends on independently established requirement/authority/criteria and actual exists/authenticated/admitted proofs, not a recovery/assembly label.',classification_origin_still_distinguishes_legacy_labels=True,accepted_normative_predicate_changed=False,draft_was_overrestrictive_and_never_false_closed=True,actual_source_absent_in_both_assessments=True,actual_domain_closures=0,superseded_evidence='superseded-draft-v1/archive-record.json',current_phase2_resumption_requires_refreshed_two_phase1_reviews=True,phase2_rerun_by_this_script=False))
print(json.dumps(dict(status='PHASE1_REVISION2_READY',mandatory_tests='6/6',origin_neutrality_control='PASS',phase2_rerun=False)))
